<script setup lang="ts">
import { ref,onMounted } from 'vue'
import { get,post,patch } from '../api'
import { useSession } from '../stores/session'
import { ElMessage } from 'element-plus'
const auth=useSession(),rows=ref<any[]>([]),communities=ref<any[]>([]),page=ref(1),total=ref(0),open=ref(false),saving=ref(false),form=ref<any>({})
async function load(){const r=await get('/support/knowledge',{editing:true,page:page.value});rows.value=r.records;total.value=r.total}
function edit(row?:any){form.value=row?{...row}:{communityId:auth.roles.includes('SUPER_ADMIN')?null:communities.value[0]?.id,title:'',keywords:'',question:'',answer:'',audience:'ALL',status:'DRAFT',version:0};open.value=true}
async function save(){if(saving.value)return;saving.value=true;try{const f=form.value;if(f.id)await patch('/support/knowledge/'+f.id,f);else await post('/support/knowledge',f);open.value=false;ElMessage.success(f.status==='PUBLISHED'?'问答已发布':'草稿已保存');await load()}finally{saving.value=false}}
onMounted(async()=>{communities.value=(await get('/support/options')).communities;await load()})
</script>
<template><div class="page-heading"><div><h1>客服知识库</h1><p class="muted">发布准确的说明，让居民和维修人员更快找到答案。</p></div><el-button type="primary" @click="edit()">新建问答</el-button></div>
<el-table :data="rows"><el-table-column prop="title" label="标题"/><el-table-column label="适用范围"><template #default="{row}">{{communities.find(c=>c.id===row.communityId)?.name||(row.communityId?'小区已停用':'全平台')}}</template></el-table-column><el-table-column label="服务对象"><template #default="{row}">{{row.audience==='ALL'?'居民与维修人员':row.audience==='RESIDENT'?'居民':'维修人员'}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{row.status==='PUBLISHED'?'已发布':'草稿'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="edit(row)">编辑 / 撤回发布</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next" @current-change="load"/>
<el-dialog v-model="open" title="维护客服问答" width="640px"><el-form label-position="top"><el-form-item label="适用范围"><el-select v-model="form.communityId"><el-option v-if="auth.roles.includes('SUPER_ADMIN')" :value="null as any" label="全平台"/><el-option v-for="c in communities" :key="c.id" :value="c.id" :label="c.name"/></el-select></el-form-item><el-form-item label="标题"><el-input v-model="form.title" maxlength="100"/></el-form-item><el-form-item label="关键词（用空格分隔）"><el-input v-model="form.keywords" maxlength="300" placeholder="例如：绑定 房屋 审核"/></el-form-item><el-form-item label="用户问题"><el-input v-model="form.question" maxlength="500"/></el-form-item><el-form-item label="答案"><el-input v-model="form.answer" type="textarea" :rows="5" maxlength="2000" show-word-limit/></el-form-item><el-form-item label="服务对象"><el-select v-model="form.audience"><el-option value="ALL" label="居民与维修人员"/><el-option value="RESIDENT" label="居民"/><el-option value="WORKER" label="维修人员"/></el-select></el-form-item><el-form-item label="发布状态"><el-select v-model="form.status"><el-option value="DRAFT" label="草稿（不供客服引用）"/><el-option value="PUBLISHED" label="发布"/></el-select></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></template>
